def button(text, href='/contact', style='', arrow=True):
    return f'<a class="btn {style}" href="{e(href,quote=True)}">{e(text)}{("<span aria-hidden=true>→</span>" if href.startswith("http") else "<span aria-hidden=true>→</span>") if arrow else ""}</a>'


def service_rows():
    return '<div class="services-list">'+''.join(f'<a class="service-row" href="/services/{s["slug"]}"><span class="number">0{i+1}</span><h3>{e(s["name"])}</h3><p>{e(s["summary"])}</p><span class="arrow" aria-hidden="true">→</span></a>' for i,s in enumerate(SERVICES))+'</div>'


def steps(light=False):
    items=[('Scope the work','Share plans, quantities, site conditions and the required completion date. We identify the construction package and engineering interfaces.'),('Coordinate the field','Align access, materials, utility requirements, permitting dependencies and specialist responsibilities before mobilization.'),('Build & document','Coordinate execution, resolve field questions and track progress against the agreed scope.'),('Close out the package','Reconcile redlines and quantities, resolve punch-list items and assemble the owner’s turnover records.')]
    return '<ol class="steps">'+''.join(f'<li><span class="number">0{i+1}</span><div><h3>{e(title)}</h3><p>{e(text)}</p></div></li>' for i,(title,text) in enumerate(items))+'</ol>'


def cta():
    return f'<section class="bottom-cta"><div class="wrap"><div><h2>Bring us the plans.<br>Let’s define the build.</h2><p>Start with your route, site or bid package. Our team will help coordinate the construction scope and next steps.</p></div>{button("Discuss your project")}</div></section>'


