for path,(title,description,content,active) in PAGES.items():
    target=OUTPUT/('index.html' if path=='/' else path.lstrip('/')+'.html')
    target.parent.mkdir(parents=True,exist_ok=True)
    target.write_text(layout(path,title,description,content,active))
(OUTPUT/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{BASE}{path}</loc></url>' for path in PAGES)+'</urlset>\n')
(OUTPUT/'robots.txt').write_text('User-agent: *\nAllow: /\nSitemap: '+BASE+'/sitemap.xml\n')
(OUTPUT/'404.html').write_text(layout('/404','Page Not Found','Find Odiscom Construction services and project contacts.',page_hero('Page not found','Let’s get you to the right place.','Explore our construction services or contact our team about your project.',f'<div class="actions">{button("View services","/services")}</div>')))
